import React, { useState } from "react";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";

export default function ExcelFilter() {
  const [excelData, setExcelData] = useState([]);
  const [results, setResults] = useState([]);

  const [startDate, setStartDate] = useState("");

  const [endDate, setEndDate] = useState("");

  const [employeeInput, setEmployeeInput] = useState("");

  const normalizeText = (text) => {
    if (!text) return "";

    return text
      .toString()
      .normalize("NFC")
      .trim()
      .toLowerCase()
      .replace(/\s+/g, " ");
  };

  // Parse date an toàn
  const parseDate = (value) => {
    if (!value) return null;

    // Nếu là Date object
    if (value instanceof Date) {
      return value;
    }

    // Nếu là number của Excel
    if (!isNaN(value)) {
      const excelDate = XLSX.SSF.parse_date_code(value);

      if (!excelDate) return null;

      return new Date(excelDate.y, excelDate.m - 1, excelDate.d);
    }

    // Nếu là string
    const str = value.toString().trim();

    // dd/mm/yyyy
    if (str.includes("/")) {
      const onlyDate = str.split(" ")[0];

      const parts = onlyDate.split("/");

      if (parts.length !== 3) return null;

      return new Date(Number(parts[2]), Number(parts[1]) - 1, Number(parts[0]));
    }

    // yyyy-mm-dd
    return new Date(str);
  };

  // Upload file
  const handleFileUpload = (e) => {
    const file = e.target.files[0];

    if (!file) return;

    const reader = new FileReader();

    reader.onload = (evt) => {
      const data = evt.target.result;

      const workbook = XLSX.read(data, {
        type: "binary",
      });

      const worksheet = workbook.Sheets["BP.DVKH gửi nội dung Phản ánh"];

      if (!worksheet) {
        alert("Không tìm thấy sheet!");

        return;
      }

      const jsonData = XLSX.utils.sheet_to_json(worksheet, {
        raw: true,
        defval: "",

        // Header bắt đầu từ dòng 3
        range: 1,
      });

      console.log("DATA EXCEL:", jsonData);

      setExcelData(jsonData);

      console.log("DATA:", jsonData);

      if (jsonData.length > 0) {
        console.log("HEADER:", Object.keys(jsonData[0]));

        console.log("FIRST ROW:", jsonData[0]);
      }

      alert("Upload Excel thành công!");
    };

    reader.readAsBinaryString(file);
  };

  // Filter
  const handleFilter = () => {
    if (!startDate || !endDate) {
      alert("Vui lòng chọn ngày!");

      return;
    }

    // Set time
    const start = new Date(startDate);
    start.setHours(0, 0, 0, 0);

    const end = new Date(endDate);
    end.setHours(23, 59, 59, 999);

    // Mảng nhân viên
    const employeeArray = employeeInput
      .split(",")
      .map((x) => normalizeText(x))
      .filter(Boolean);

    console.log("EMPLOYEE ARRAY:", employeeArray);

    const filtered = excelData.filter((row) => {
      // Tìm key động
      const employeeKey = Object.keys(row).find((k) =>
        k.toLowerCase().includes("tên nhân viên qlcl-dv"),
      );

      const dateKey = Object.keys(row).find((k) =>
        k.toLowerCase().includes("ngày phản hồi"),
      );

      const contentKey = Object.keys(row).find((k) =>
        k.toLowerCase().includes("nội dung tiếp nhận"),
      );

      if (!employeeKey || !dateKey || !contentKey) {
        return false;
      }

      // Data excel
      const excelEmployee = normalizeText(row[employeeKey]);

      const excelDate = parseDate(row[dateKey]);

      console.log({
        excelEmployee,
        excelDate,
      });

      if (!excelDate) return false;

      // Compare
      const isEmployeeMatch = employeeArray.includes(excelEmployee);

      const isDateMatch = excelDate >= start && excelDate <= end;

      return isEmployeeMatch && isDateMatch;
    });

    console.log("FILTERED:", filtered);

    setResults(filtered);

    if (filtered.length === 0) {
      alert("Không tìm thấy dữ liệu!");
    }
  };

  // Export excel
  const handleExportExcel = () => {
    if (results.length === 0) {
      alert("Không có dữ liệu!");

      return;
    }

    const exportData = results.map((row, index) => ({
      STT: index + 1,

      "Ngày phản hồi": row["Ngày phản hồi"],

      "Tên nhân viên QLCL-DV": row["Tên nhân viên QLCL-DV"],

      "Nội dung tiếp nhận Phản ánh": row["Nội dung tiếp nhận Phản ánh"],
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);

    worksheet["!cols"] = [{ wch: 10 }, { wch: 20 }, { wch: 30 }, { wch: 100 }];

    const workbook = XLSX.utils.book_new();

    XLSX.utils.book_append_sheet(workbook, worksheet, "KetQua");

    const excelBuffer = XLSX.write(workbook, {
      bookType: "xlsx",
      type: "array",
    });

    const blob = new Blob([excelBuffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=UTF-8",
    });

    saveAs(blob, `KetQua_${Date.now()}.xlsx`);
  };

  return (
    <div
      style={{
        padding: 30,
      }}
    >
      <h1>Tra cứu phản ánh</h1>

      <div
        style={{
          marginBottom: 20,
        }}
      >
        <input type="file" accept=".xlsx,.xls" onChange={handleFileUpload} />
      </div>

      <div
        style={{
          marginBottom: 20,
        }}
      >
        <label>Ngày bắt đầu</label>

        <br />

        <input
          type="date"
          value={startDate}
          onChange={(e) => setStartDate(e.target.value)}
        />
      </div>

      <div
        style={{
          marginBottom: 20,
        }}
      >
        <label>Ngày kết thúc</label>

        <br />

        <input
          type="date"
          value={endDate}
          onChange={(e) => setEndDate(e.target.value)}
        />
      </div>

      <div
        style={{
          marginBottom: 20,
        }}
      >
        <label>Tên nhân viên</label>

        <br />

        <input
          type="text"
          placeholder="VD: Nguyễn Văn A, Trần Thị B"
          value={employeeInput}
          onChange={(e) => setEmployeeInput(e.target.value)}
          style={{
            width: 500,
            padding: 10,
          }}
        />
      </div>

      <button onClick={handleFilter}>Tìm kiếm</button>

      <button
        onClick={handleExportExcel}
        style={{
          marginLeft: 10,
        }}
      >
        Export Excel
      </button>

      <hr />

      <table
        border="1"
        cellPadding="10"
        style={{
          width: "100%",
          borderCollapse: "collapse",
        }}
      >
        <thead>
          <tr>
            <th>STT</th>
            <th>Ngày phản hồi</th>
            <th>Tên nhân viên</th>
            <th>Nội dung tiếp nhận</th>
          </tr>
        </thead>

        <tbody>
          {results.map((row, index) => (
            <tr key={index}>
              <td>{index + 1}</td>

              <td>{row["Ngày phản hồi"]}</td>

              <td>{row["Tên nhân viên QLCL-DV"]}</td>

              <td>{row["Nội dung tiếp nhận Phản ánh"]}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
